std::vector<size_t> GetNearestNeighborsSimplified(const std::vector<Point3D>& points, const Point3D& searchPoint, std::size_t k) {
    if (points.empty() || k == 0) {
        return {};
    }

    k = std::min(k, points.size());

    auto distanceSquared = [](const Point3D& a, const Point3D& b) {
        float dx = a.x - b.x;
        float dy = a.y - b.y;
        float dz = a.z - b.z;
        return dx * dx + dy * dy + dz * dz;
    };

    using DistanceIndex = std::pair<float, size_t>;
    auto cmp = [](const DistanceIndex& a, const DistanceIndex& b) {
        return a.first < b.first;
    };
    std::priority_queue<DistanceIndex, std::vector<DistanceIndex>, decltype(cmp)> maxHeap(cmp);

    for (size_t i = 0; i < points.size(); ++i) {
        float distSq = distanceSquared(points[i], searchPoint);

        if (maxHeap.size() < k) {
            maxHeap.emplace(distSq, i);
        } else if (distSq < maxHeap.top().first) {
            maxHeap.pop();
            maxHeap.emplace(distSq, i);
        }
    }

    std::vector<size_t> result;
    result.reserve(maxHeap.size());

    while (!maxHeap.empty()) {
        result.push_back(maxHeap.top().second);
        maxHeap.pop();
    }

    std::reverse(result.begin(), result.end());
    return result;
}

